        "text": "11월 28일에 풀이한 논문들 중에서는 인공지능 모델과 학습법을 다룬 연구들이 가장 많이 눈에 띄었고, 그 다음으로 AI 안전과 평가를 다룬 내용들이 뒤를 이었는데요. 이와 함께 전력망 제어나 로봇 제어 같은 물리 시스템 분야도 여러 편 올라왔다는 겁니다. 예컨대 순환 상태 불안정성을 해결하려는 Gated DeltaNet-2 제안이나, 여러 플랫폼을 넘나드는 컴퓨터 사용 에이전트를 평가하는 OS-Omni 개발 같은 작업들이 그런 식인데요. 쉽게 말하면 인공지능의 성능을 높이거나 안전하게 다듬는 연구 쪽으로 힘이 실렸다는 말이에요.",
